//! Opt-in format-aware tag publication. Audio is never decoded or transcoded.
use anyhow::{ensure,Context,Result};
use lofty::{file::{TaggedFileExt,AudioFile},tag::{ItemKey,Tag,TagExt,Accessor},config::WriteOptions};
use musicos_init::database::{Db,MetadataUpdate};
use serde::{Serialize,Deserialize};
use sha2::{Digest,Sha256};
use std::{path::{Path,PathBuf},io::Read,sync::{Mutex,OnceLock},time::SystemTime};
#[derive(Serialize,Deserialize)]struct FileChange{track_id:i64,path:PathBuf,backup:PathBuf,staged:PathBuf,before:String,after:String,modified:SystemTime}
#[derive(Serialize,Deserialize)]struct Job{id:String,history_id:Option<i64>,state:String,files:Vec<FileChange>}
fn directory(db:&Path)->PathBuf{db.with_extension("tag-backups")}
fn hash(path:&Path)->Result<String>{let mut file=std::fs::File::open(path)?;let mut hash=Sha256::new();let mut bytes=[0u8;65536];loop{let n=file.read(&mut bytes)?;if n==0{break;}hash.update(&bytes[..n]);}Ok(format!("{:x}",hash.finalize()))}
fn save(db:&Path,job:&Job)->Result<()>{musicos_desktop::storage::atomic_write_json(&directory(db).join(&job.id).join("job.json"),job)}
fn serial()->&'static Mutex<()>{static LOCK:OnceLock<Mutex<()>>=OnceLock::new();LOCK.get_or_init(Default::default)}
fn fields(patch:&MetadataUpdate)->[(ItemKey,Option<String>);7]{[(ItemKey::TrackTitle,patch.title.clone()),(ItemKey::TrackArtist,patch.artist.clone()),(ItemKey::AlbumTitle,patch.album.clone()),(ItemKey::AlbumArtist,patch.album_artist.clone()),(ItemKey::Genre,patch.genre.clone()),(ItemKey::TrackNumber,patch.track_number.map(|n|n.to_string())),(ItemKey::DiscNumber,patch.disc_number.map(|n|n.to_string()))]}
fn inspect(path:&Path)->Result<(u64,SystemTime)>{let m=std::fs::symlink_metadata(path).with_context(||format!("Cannot access {}. Choose its folder again to grant access.",path.display()))?;ensure!(m.is_file()&&!m.file_type().is_symlink(),"Choose an original music file, not a symbolic link");ensure!(!m.permissions().readonly(),"{} is read-only",path.display());#[cfg(unix)]{use std::os::unix::fs::MetadataExt;ensure!(m.nlink()==1,"{} has linked copies; tag it separately to avoid breaking those links",path.display());}Ok((m.len(),m.modified()?))}
pub fn preflight(db:&Path,ids:&[i64])->Result<serde_json::Value>{ensure!(!ids.is_empty()&&ids.len()<=10000,"Choose songs to write");let database=Db::open(&db.to_string_lossy())?;let mut files=Vec::new();let mut bytes=0u64;for id in ids{let track=database.get_track_by_id(*id)?.context("Song no longer exists")?;let path=PathBuf::from(track.path);let result=(||->Result<_>{let(size,_)=inspect(&path)?;let tagged=lofty::read_from_path(&path)?;bytes=bytes.saturating_add(size);Ok(format!("{:?}",tagged.primary_tag_type()))})();files.push(serde_json::json!({"track_id":id,"path":path,"format":result.as_ref().ok(),"error":result.as_ref().err().map(ToString::to_string)}));}let parent=db.parent().context("Missing backup folder")?;ensure!(fs2::available_space(parent)?>bytes.saturating_add(32*1024*1024),"Not enough space for original-file backups");Ok(serde_json::json!({"files":files,"backup_bytes":bytes,"supported_fields":["Title","Artist","Album","Album artist","Genre","Year","Disc and track numbers","Front artwork"]}))}
fn restore(file:&FileChange)->Result<()>{let current=hash(&file.path)?;ensure!(current==file.before||(!file.after.is_empty()&&current==file.after),"{} changed after tagging; compare it before restoring",file.path.display());if current!=file.before{ensure!(hash(&file.backup)?==file.before,"The original backup changed");let temp=file.path.with_file_name(format!(".musicos-restore-{}",file.track_id));let mut dest=std::fs::OpenOptions::new().write(true).create_new(true).open(&temp)?;let result=(||->Result<()>{std::io::copy(&mut std::fs::File::open(&file.backup)?,&mut dest)?;dest.set_permissions(file.backup.metadata()?.permissions())?;dest.set_times(std::fs::FileTimes::new().set_modified(file.modified))?;dest.sync_all()?;std::fs::rename(&temp,&file.path)?;Ok(())})();if result.is_err(){let _=std::fs::remove_file(temp);}result?;}Ok(())}
fn sync_identity(database:&Db,history:i64,file:&FileChange)->Result<()>{let m=file.path.metadata()?;database.record_tag_identity(history,file.track_id,m.len() as i64,m.modified()?.duration_since(SystemTime::UNIX_EPOCH)?.as_secs() as i64,&hash(&file.path)?)?;Ok(())}
fn cleanup(job:&Job){for f in &job.files{let _=std::fs::remove_file(&f.staged);}}
fn prepare(db:&Path,changes:&[(i64,MetadataUpdate)])->Result<Job>{
 let preflight=preflight(db,&changes.iter().map(|c|c.0).collect::<Vec<_>>())?;ensure!(preflight["files"].as_array().unwrap().iter().all(|f|f["error"].is_null()),"Some files cannot be written. Review file access and formats first.");let database=Db::open(&db.to_string_lossy())?;let id=SystemTime::now().duration_since(SystemTime::UNIX_EPOCH)?.as_nanos().to_string();let dir=directory(db).join(&id);std::fs::create_dir_all(&dir)?;let mut job=Job{id,history_id:None,state:"preparing".into(),files:Vec::new()};save(db,&job)?;
 let result=(||->Result<()>{for (id,patch) in changes{let path=PathBuf::from(database.get_track_by_id(*id)?.context("Song no longer exists")?.path);let(size,modified)=inspect(&path)?;ensure!(fs2::available_space(path.parent().context("Missing music folder")?)?>size.saturating_add(32*1024*1024),"Not enough space to stage {}",path.display());let backup=dir.join(format!("{id}.original"));let staged=path.with_file_name(format!(".musicos-tags-{}-{id}.{}",job.id,path.extension().unwrap_or_default().to_string_lossy()));let before=hash(&path)?;
 job.files.push(FileChange{track_id:*id,path:path.clone(),backup:backup.clone(),staged:staged.clone(),before:before.clone(),after:String::new(),modified});save(db,&job)?;
 let mut dest=std::fs::OpenOptions::new().write(true).create_new(true).open(&staged).with_context(||format!("Cannot write beside {}. Choose the containing folder again.",path.display()))?;std::io::copy(&mut std::fs::File::open(&path)?,&mut dest)?;dest.sync_all()?;std::fs::copy(&path,&backup)?;std::fs::File::open(&backup)?.sync_all()?;ensure!(hash(&backup)?==before&&hash(&path)?==before,"A music file changed while backing up");
 let mut tagged=lofty::read_from_path(&staged).context("This file cannot be safely tagged")?;let properties=tagged.properties().clone();let tag_type=tagged.primary_tag_type();if tagged.primary_tag().is_none(){tagged.insert_tag(Tag::new(tag_type));}let tag=tagged.primary_tag_mut().context("No writable tag container")?;
 for (key,value) in fields(patch){if let Some(value)=value{tag.remove_key(&key);if !value.is_empty()&&!(value=="0"&&matches!(key,ItemKey::TrackNumber|ItemKey::DiscNumber)){let name=format!("{key:?}");ensure!(tag.insert_text(key,value),"This {tag_type:?} file cannot store {name}; original retained");}}}
 if let Some(year)=patch.year{if year==0{tag.remove_year();}else{tag.set_year(year as u32);}}
 if let Some(art)=&patch.artwork_path{let bytes=std::fs::read(art)?;ensure!(bytes.len()<=20*1024*1024,"Artwork is too large to embed");let mut picture=lofty::picture::Picture::from_reader(&mut std::io::Cursor::new(bytes))?;picture.set_pic_type(lofty::picture::PictureType::CoverFront);tag.remove_picture_type(lofty::picture::PictureType::CoverFront);tag.push_picture(picture);}
 std::fs::set_permissions(&staged,path.metadata()?.permissions())?;tag.save_to_path(&staged,WriteOptions::default()).context("Unable to stage tags; original file retained")?;let checked=lofty::read_from_path(&staged)?;ensure!(checked.properties().sample_rate()==properties.sample_rate()&&checked.properties().channels()==properties.channels()&&checked.properties().bit_depth()==properties.bit_depth()&&checked.properties().duration().abs_diff(properties.duration())<std::time::Duration::from_millis(2),"Audio properties changed while staging tags");let verified=checked.primary_tag().context("Tag verification failed")?;for(key,value)in fields(patch){if let Some(value)=value{let expected=if value=="0"&&matches!(key,ItemKey::TrackNumber|ItemKey::DiscNumber){String::new()}else{value};ensure!(verified.get_string(&key).unwrap_or("")==expected,"This format did not preserve a requested field; original retained");}}
 if let Some(year)=patch.year{ensure!(verified.year()==(year>0).then_some(year as u32),"Year was not preserved; original retained");}
 if patch.artwork_path.is_some(){ensure!(verified.pictures().iter().any(|p|p.pic_type()==lofty::picture::PictureType::CoverFront),"Artwork was not preserved");}std::fs::File::open(&staged)?.sync_all()?;job.files.last_mut().unwrap().after=hash(&staged)?;save(db,&job)?;
 }Ok(())})();if let Err(error)=result{cleanup(&job);job.state="not_applied".into();save(db,&job)?;return Err(error);}job.state="prepared".into();save(db,&job)?;Ok(job)
}
pub fn apply(db:&Path,changes:&[(i64,MetadataUpdate)],reviews:&[(i64,i64,String)],write:bool)->Result<(usize,i64)>{let database=Db::open(&db.to_string_lossy())?;if !write{return database.update_metadata_batch(changes,reviews);}let _serial=serial().lock().unwrap_or_else(|e|e.into_inner());let mut job=prepare(db,changes)?;
 let _=database.metadata_history()?;let _writer=database.reserve_writer()?;let result=(||->Result<(usize,i64)>{for file in &job.files{ensure!(hash(&file.path)?==file.before,"A music file changed during preparation");}job.state="publishing".into();save(db,&job)?;let(count,id)=database.update_metadata_batch_with_file_job(changes,reviews,Some(&job.id))?;job.history_id=Some(id);save(db,&job)?;for file in &job.files{ensure!(hash(&file.path)?==file.before,"A file changed before publication");std::fs::rename(&file.staged,&file.path)?;sync_identity(&database,id,file)?;}job.state="complete".into();save(db,&job)?;Ok((count,id))})();if result.is_err(){// A durable SQL job identity closes the commit-to-journal crash window.
 job.history_id=database.file_job_history(&job.id)?;if let Some(id)=job.history_id{for file in &job.files{restore(file)?;sync_identity(&database,id,file)?;}database.undo_metadata_change(id)?;}cleanup(&job);job.state="rolled_back".into();save(db,&job)?;}result}
fn undo_job(db:&Path,database:&Db,job:&mut Job)->Result<()>{let id=job.history_id.context("Missing history record")?;database.check_metadata_undo(id)?;for file in &job.files{ensure!(database.get_track_by_id(file.track_id)?.is_some(),"Some songs were forgotten. File Undo is unavailable; original backups are retained.");ensure!(hash(&file.path)?==file.after,"A tagged file changed. Compare it before Undo.");ensure!(hash(&file.backup)?==file.before,"Original backup is unavailable");}job.state="undoing".into();save(db,job)?;finish_undo(db,database,job)}
fn finish_undo(db:&Path,database:&Db,job:&mut Job)->Result<()>{let id=job.history_id.context("Missing history record")?;for file in &job.files{restore(file)?;sync_identity(database,id,file)?;}let history=database.metadata_history()?;if !history.as_array().unwrap().iter().any(|h|h["id"]==id&&h["undone"]==true){database.undo_metadata_change(id)?;}job.state="undone".into();save(db,job)}
pub fn undo(db:&Path,history_id:i64)->Result<()>{let _serial=serial().lock().unwrap_or_else(|e|e.into_inner());let database=Db::open(&db.to_string_lossy())?;let _=database.metadata_history()?;let _writer=database.reserve_writer()?;for mut job in jobs(db)?{if job.history_id==Some(history_id){ensure!(job.state!="backup_removed","Original-file backups were removed; file Undo is unavailable");ensure!(["complete","undone","rolled_back"].contains(&job.state.as_str()),"Finish interrupted file recovery before Undo");if job.state=="complete"{return undo_job(db,&database,&mut job);}}}database.undo_metadata_change(history_id)}
pub fn restores_files(db:&Path,id:i64)->Result<bool>{Ok(jobs(db)?.iter().any(|job|job.history_id==Some(id)&&matches!(job.state.as_str(),"complete"|"undoing"|"publishing")))}
fn jobs(db:&Path)->Result<Vec<Job>>{let dir=directory(db);let mut jobs=Vec::new();if dir.exists(){for entry in std::fs::read_dir(dir)?{let path=entry?.path().join("job.json");if path.exists(){jobs.push(serde_json::from_slice(&std::fs::read(path)?)?);}}}Ok(jobs)}
pub fn recover(db:&Path)->Result<()>{let _serial=serial().lock().unwrap_or_else(|e|e.into_inner());let database=Db::open(&db.to_string_lossy())?;let _=database.metadata_history()?;let _writer=database.reserve_writer()?;for mut job in jobs(db)?{if job.state=="publishing"{job.history_id=database.file_job_history(&job.id)?;if let Some(id)=job.history_id{for file in &job.files{restore(file)?;sync_identity(&database,id,file)?;}database.undo_metadata_change(id)?;}job.state="rolled_back".into();save(db,&job)?;}else if job.state=="undoing"{finish_undo(db,&database,&mut job)?;}if matches!(job.state.as_str(),"preparing"|"prepared"|"not_applied"|"rolled_back"){cleanup(&job);}}Ok(())}
pub fn status(db:&Path)->Result<serde_json::Value>{let items=jobs(db)?.into_iter().map(|job|{let bytes=job.files.iter().filter_map(|f|f.backup.metadata().ok()).map(|m|m.len()).sum::<u64>();serde_json::json!({"id":job.id,"history_id":job.history_id,"state":job.state,"bytes":bytes,"files":job.files.len()})}).collect::<Vec<_>>();Ok(serde_json::json!({"jobs":items}))}
pub fn remove_backup(db:&Path,id:&str)->Result<()>{let _serial=serial().lock().unwrap_or_else(|e|e.into_inner());ensure!(!id.is_empty()&&id.bytes().all(|b|b.is_ascii_digit()),"Invalid backup");let path=directory(db).join(id);let mut job:Job=serde_json::from_slice(&std::fs::read(path.join("job.json"))?)?;ensure!(["complete","undone","rolled_back","not_applied"].contains(&job.state.as_str()),"Finish recovery before removing this backup");for file in &job.files{if file.backup.exists(){std::fs::remove_file(&file.backup)?;}}job.state="backup_removed".into();save(db,&job)}
#[cfg(test)]mod tests{
 use super::*;
 fn fixture(codec:&str,ext:&str)->(tempfile::TempDir,PathBuf,PathBuf,i64){let tmp=tempfile::tempdir().unwrap();let audio=tmp.path().join(format!("song.{ext}"));assert!(std::process::Command::new("/opt/homebrew/bin/ffmpeg").args(["-v","error","-f","lavfi","-i","sine=frequency=440:duration=0.2","-c:a",codec]).arg(&audio).status().unwrap().success());let path=tmp.path().join("library.db");let db=Db::open(&path.to_string_lossy()).unwrap();let id=db.insert_track(&audio.to_string_lossy(),"Original","Artist","Album",1,1,1).unwrap();(tmp,path,audio,id)}
 fn pcm(path:&Path)->String{let output=std::process::Command::new("/opt/homebrew/bin/ffmpeg").args(["-v","error","-i"]).arg(path).args(["-f","s16le","-"]).output().unwrap();assert!(output.status.success());format!("{:x}",Sha256::digest(output.stdout))}
 #[test]fn tag_round_trip_preserves_audio_and_undo_restores_exact_original(){for(codec,ext)in[("flac","flac"),("alac","m4a"),("libmp3lame","mp3")]{let(_tmp,path,audio,id)=fixture(codec,ext);let original=std::fs::read(&audio).unwrap();let audio_hash=pcm(&audio);let(_,history)=apply(&path,&[(id,MetadataUpdate{title:Some("New title".into()),artist:Some("One & Two".into()),album_artist:Some("One".into()),album:Some("Record".into()),genre:Some("Jazz".into()),year:Some(2020),track_number:Some(2),disc_number:Some(1),..Default::default()})],&[],true).unwrap();assert_eq!(pcm(&audio),audio_hash);assert_eq!(lofty::read_from_path(&audio).unwrap().primary_tag().unwrap().get_string(&ItemKey::TrackTitle),Some("New title"));assert!(status(&path).unwrap()["jobs"][0]["bytes"].as_u64().unwrap()>0);undo(&path,history).unwrap();assert_eq!(std::fs::read(audio).unwrap(),original);assert_eq!(Db::open(&path.to_string_lossy()).unwrap().get_track_by_id(id).unwrap().unwrap().title,"Original");}}
 #[test]fn musicos_only_and_conflicting_undo_never_touch_originals(){let(_tmp,path,audio,id)=fixture("flac","flac");let before=hash(&audio).unwrap();apply(&path,&[(id,MetadataUpdate{genre:Some("Jazz".into()),..Default::default()})],&[],false).unwrap();assert_eq!(hash(&audio).unwrap(),before);let(_,history)=apply(&path,&[(id,MetadataUpdate{title:Some("First".into()),..Default::default()})],&[],true).unwrap();let tagged=hash(&audio).unwrap();apply(&path,&[(id,MetadataUpdate{title:Some("Later".into()),..Default::default()})],&[],false).unwrap();assert!(undo(&path,history).is_err());assert_eq!(hash(&audio).unwrap(),tagged);}
 #[test]fn interrupted_publication_recovers_and_removed_backups_disable_file_undo(){let(_tmp,path,audio,id)=fixture("flac","flac");let before=hash(&audio).unwrap();let(_,history)=apply(&path,&[(id,MetadataUpdate{title:Some("New".into()),..Default::default()})],&[],true).unwrap();let mut job=jobs(&path).unwrap().remove(0);job.state="publishing".into();save(&path,&job).unwrap();recover(&path).unwrap();assert_eq!(hash(&audio).unwrap(),before);assert!(Db::open(&path.to_string_lossy()).unwrap().metadata_history().unwrap().as_array().unwrap().iter().any(|h|h["id"]==history&&h["undone"]==true));let(_,history)=apply(&path,&[(id,MetadataUpdate{title:Some("Another".into()),..Default::default()})],&[],true).unwrap();let job=jobs(&path).unwrap().into_iter().find(|j|j.history_id==Some(history)).unwrap();remove_backup(&path,&job.id).unwrap();let tagged=hash(&audio).unwrap();assert!(undo(&path,history).is_err());assert_eq!(hash(&audio).unwrap(),tagged);}
 #[test]fn preparation_failure_cleans_staging_without_mutating_metadata(){let(_tmp,path,audio,id)=fixture("flac","flac");let before=hash(&audio).unwrap();let missing=audio.with_extension("missing.png");assert!(apply(&path,&[(id,MetadataUpdate{artwork_path:Some(missing.to_string_lossy().into_owned()),..Default::default()})],&[],true).is_err());assert_eq!(hash(&audio).unwrap(),before);assert!(!std::fs::read_dir(audio.parent().unwrap()).unwrap().any(|e|e.unwrap().file_name().to_string_lossy().starts_with(".musicos-tags-")));assert!(Db::open(&path.to_string_lossy()).unwrap().metadata_history().unwrap().as_array().unwrap().is_empty());}
}
